function buildTrees(b){for(const [label,data,tree] of [['科技',game.techTree||[],state().tech],['市政',game.civicTree||[],state().civic]]){b.append(el('h3',label+' · 格物致知'));const tiers=[...new Set(data.map(n=>n.tier))].sort((a,b)=>a-b);for(const tier of tiers){b.append(el('h4','第 '+tier+' 代'));const grid=el('div','','tree-grid');for(const n of data.filter(n=>n.tier===tier)){const status=tree.unlocked.includes(n.id)?'已解锁':n.prereqs.every(id=>tree.unlocked.includes(id))?'可用':'锁定';const card=el('section','','tree-node '+({已解锁:'unlocked',可用:'available',锁定:'locked'}[status]));const progress=tree.unlocked.includes(n.id)?n.cost:tree.progress[n.id]||0;card.append(el('small',status),el('h4',n.name),el('p','进度 '+progress+' / '+n.cost));const bar=el('div','','bar');const fill=el('i');fill.style.width=Math.min(100,progress/n.cost*100)+'%';bar.append(fill);card.append(bar,el('p',effectText(n.effects)),el('p',n.flavor||''));if(n.prereqs.length)card.append(el('small','前置：'+n.prereqs.map(id=>data.find(x=>x.id===id)?.name||id).join('、')));grid.append(card)}b.append(grid)}}}
function requestId(){
 if(typeof crypto.randomUUID==='function')return crypto.randomUUID();
 const bytes=crypto.getRandomValues(new Uint8Array(16));bytes[6]=(bytes[6]&15)|64;bytes[8]=(bytes[8]&63)|128;
 const hex=Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');return [hex.slice(0,8),hex.slice(8,12),hex.slice(12,16),hex.slice(16,20),hex.slice(20)].join('-');
}
function envelope(action){return {...action,gameId:state().id,revision:state().revision,requestId:requestId()}}
async function execute(){if(busy||!pendingRequest)return;busy=true;synchronize();const request=pendingRequest;setBusy(request.kind);let report=false;try{const response=await api(request.url,request.body);game=response;pendingRequest=null;if(request.kind==='turn'){orders=[];eventChoice=-1;decree='';privyRelease=0;report=true}if(request.kind==='chat'){const history=chats[request.body.ministerId]||(chats[request.body.ministerId]=[]);history.push({who:'me',text:request.body.message},{who:'them',text:response.reply||'此问已处理，回复未由服务器重放。'});}render();if(state().ending){$('overlay').hidden=true;modal=null;document.body.classList.remove('modal-open')}else refreshModal();say('已处理，进度已保存。')}catch(e){if(e.status>=400&&e.status<500){pendingRequest=null;if(e.status===409){try{game=await api('/api/game');render();refreshModal()}catch{say('存档刷新失败，请重新读取存档。',true)}}}if(e.status===401){token=null;localStorage.removeItem('ming-token');game=null;$('overlay').hidden=true;modal=null;showAuth('登录已过期，请重新登录。')}else say(e.message,true)}finally{busy=false;synchronize();if(report&&game&&!state().ending)openModal('时局汇总 · '+reignOf(state().turn),buildReport)}}
function mutate(url,action,kind){if(busy)return;if(pendingRequest){say('有未确认请求，请先重试原请求或重新读取存档。',true);return}try{pendingRequest={url,body:envelope(action),kind};execute()}catch(e){pendingRequest=null;say('无法提交操作：'+e.message,true)}}
function submitTurn(action){if(!pendingRequest)closeModal();mutate('/api/turn',{...action,mode,orders:structuredClone(orders),eventChoice,privyRelease},'turn')}
function officeAction(action){mutate('/api/office',action,'office')}
function armyAction(action){mutate('/api/army',action,'army')}
function rivalAction(action){mutate('/api/rival',action,'rival')}
function sendChat(id,message){if(busy||pendingRequest){say('请先处理当前请求，再发送问话。',true);return}const text=(message||'').trim();if(!text){say('请输入问话。',true);return}const history=chats[id]||(chats[id]=[]);refreshModal();mutate('/api/chat',{ministerId:id,message:text},'chat')}
async function load(){if(busy)return;busy=true;synchronize();try{game=await api('/api/game');pendingRequest=null;hideAuth();render();refreshModal();say('存档已读取。')}catch(e){if(e.status===401){token=null;localStorage.removeItem('ming-token');game=null;showAuth('请登录或注册后继续。')}else{say('无法读取存档：'+e.message,true);$('reload').hidden=false}}finally{busy=false;synchronize();if(!game)$('reload').hidden=false}}
function showAuth(msg=''){$('auth-overlay').hidden=false;$('auth-msg').textContent=msg;$('auth-user').focus()}
function hideAuth(){$('auth-overlay').hidden=true}
async function auth(mode){const username=$('auth-user').value.trim(),password=$('auth-pass').value;if(!username||!password){$('auth-msg').textContent='请填写用户名和密码。';return}try{const resp=await api('/api/'+mode,{username,password});token=resp.token;localStorage.setItem('ming-token',token);hideAuth();const cfg=readAiCfg();if(cfg.apiKey||cfg.model||cfg.baseUrl){try{await api('/api/aiconfig',cfg)}catch{}}await load()}catch(e){$('auth-msg').textContent=e.message}}
function logout(){token=null;localStorage.removeItem('ming-token');game=null;showAuth('已退出登录。')}
const aiCfgKey='ming-aiconfig';
const readAiCfg=()=>{try{return JSON.parse(localStorage.getItem(aiCfgKey)||'{}')}catch{return{}}};
const writeAiCfg=c=>localStorage.setItem(aiCfgKey,JSON.stringify(c));
function openAiConfig(){const c=readAiCfg();$('aiconfig-key').value=c.apiKey||'';$('aiconfig-model').value=c.model||'deepseek-v4-pro';$('aiconfig-base').value=c.baseUrl||'';$('aiconfig-msg').textContent='';$('aiconfig-overlay').hidden=false;$('aiconfig-key').focus()}
function closeAiConfig(){$('aiconfig-overlay').hidden=true}
function openHelp(){$('help-overlay').hidden=false}
function closeHelp(){$('help-overlay').hidden=true}
async function saveAiConfig(){const c={apiKey:$('aiconfig-key').value.trim(),model:$('aiconfig-model').value.trim(),baseUrl:$('aiconfig-base').value.trim()};writeAiCfg(c);if(game&&token){try{game=await api('/api/aiconfig',c);render();$('aiconfig-msg').textContent='已保存并生效。';setTimeout(closeAiConfig,500)}catch(e){$('aiconfig-msg').textContent=e.message}}else{$('aiconfig-msg').textContent='已保存，登录后将应用到此账号。';setTimeout(closeAiConfig,600)}}
function reset(){if(!game||busy)return;if(!confirm('确定结束当前一局、清除本局进度并重新登基？'))return;pendingRequest=null;chats={};orders=[];eventChoice=-1;decree='';mutate('/api/reset',{},'reset')}
$('btn-turn').onclick=()=>game&&!state().ending&&openModal('下旨推演 · '+reignOf(state().turn),buildTurn);
$('btn-court').onclick=()=>game&&openModal('朝堂 · 大臣',buildCourt);$('btn-counsel').onclick=()=>game&&openModal('意见册 · 群臣进言',buildCounsel);$('btn-tree').onclick=()=>game&&openModal('科技 · 市政',buildTrees);$('btn-armies').onclick=()=>game&&openModal('兵部 · 军队名册',buildArmies);$('btn-rivals').onclick=()=>game&&openModal('敌情 · 对立角色',buildRivals);$('btn-report').onclick=()=>game&&openModal('时局汇总 · '+reignOf(state().turn),buildReport);
$('close').onclick=closeModal;$('overlay').onclick=e=>{if(e.target===$('overlay'))closeModal()};$('modal-retry').onclick=execute;$('modal-reload').onclick=load;$('retry').onclick=execute;$('reload').onclick=load;$('reset').onclick=reset;
$('auth-login').onclick=()=>auth('login');$('auth-signup').onclick=()=>auth('signup');$('auth-pass').addEventListener('keydown',e=>{if(e.key==='Enter')auth('login')});
$('auth-ai').onclick=openAiConfig;$('aiconfig-save').onclick=saveAiConfig;$('aiconfig-close').onclick=closeAiConfig;$('aiconfig-overlay').onclick=e=>{if(e.target.id==='aiconfig-overlay')closeAiConfig()};$('auth-help').onclick=openHelp;$('help-close').onclick=closeHelp;$('help-overlay').onclick=e=>{if(e.target.id==='help-overlay')closeHelp()};$('btn-ai').onclick=openAiConfig;$('logout').onclick=()=>{if(confirm('确定退出登录？'))logout()};
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&!$('overlay').hidden){const all=[...$('modal').querySelectorAll('button,input,select,textarea,a')].filter(n=>!n.disabled&&n.offsetParent!==null),first=all[0],last=all.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
fetch('/portraits.json').then(r=>r.ok?r.json():{}).then(data=>{portraits=data;refreshModal()}).catch(()=>{});load();

$('toggle-reports').onclick=()=>{const aside=document.querySelector('aside');const collapsed=aside.classList.toggle('collapsed');$('toggle-reports').textContent=collapsed?'天下奏报 · 展开':'天下奏报 · 收起';$('toggle-reports').setAttribute('aria-expanded',String(!collapsed))};
